// Little Hero Bot · one-time setup
// Sets the bot's name and logo, adds the slash commands to your server,
// makes #staff-applications, and connects your Cloudflare worker.
// Run:  node ~/Desktop/little-hero-bot-setup.mjs YOUR_SERVER_ID
import readline from "node:readline/promises";
import { stdin, stdout } from "node:process";
const API = process.env.LHH_API || "https://discord.com/api/v10";
const ICON = "data:image/png;base64,";
const MOD = (1n << 40n).toString(), KICK = (1n << 1n).toString(), BAN = (1n << 2n).toString(), MSGS = (1n << 13n).toString();
const user = (d = "Who?") => ({ type: 6, name: "user", description: d, required: true });
const reason = { type: 3, name: "reason", description: "Why? This goes in #mod-log", required: true, max_length: 300 };
const COMMANDS = [
  { name: "warn", description: "Send a hero a friendly rule reminder", default_member_permissions: MOD, options: [user(), reason] },
  { name: "timeout", description: "Give a hero a short break from chatting", default_member_permissions: MOD, options: [user(), { type: 4, name: "minutes", description: "How long", required: true, choices: [{ name: "10 minutes", value: 10 }, { name: "1 hour", value: 60 }, { name: "1 day", value: 1440 }, { name: "1 week", value: 10080 }] }, reason] },
  { name: "untimeout", description: "End a timeout early", default_member_permissions: MOD, options: [user()] },
  { name: "kick", description: "Remove someone from the server", default_member_permissions: KICK, options: [user(), reason] },
  { name: "ban", description: "Ban someone for serious or unsafe behavior", default_member_permissions: BAN, options: [user(), reason] },
  { name: "clear", description: "Delete recent messages in this channel", default_member_permissions: MSGS, options: [{ type: 4, name: "count", description: "How many (1 to 50)", required: true, min_value: 1, max_value: 50 }] },
  { name: "apply", description: "Apply to be an Admin or Moderator", options: [{ type: 3, name: "team", description: "Which team?", required: true, choices: [{ name: "⭐ Admin", value: "admin" }, { name: "🛡️ Moderator", value: "moderator" }] }] },
  { name: "rules", description: "Show the Hero Code" },
  { name: "play", description: "Get the link to play Little Hero" },
  { name: "Report to moderators", type: 3 },
];
let TOKEN = "";
const sleep = ms => new Promise(r => setTimeout(r, ms));
async function api(method, path, body, n = 0) {
  const r = await fetch(API + path, { method, headers: { Authorization: "Bot " + TOKEN, "content-type": "application/json", "User-Agent": "LittleHeroBot (https://be-the-doc.netlify.app, 1.0)" }, body: body === undefined ? undefined : JSON.stringify(body) });
  if (r.status === 429 && n < 5) { const j = await r.json().catch(() => ({})); await sleep((j.retry_after || 1) * 1000 + 300); return api(method, path, body, n + 1); }
  const t = await r.text(); let j = null; try { j = t ? JSON.parse(t) : null; } catch {}
  if (!r.ok) { const e = new Error(`${r.status} ${(j && j.message) || t.slice(0, 200)}`); e.status = r.status; e.body = j; throw e; }
  await sleep(300); return j;
}
const ok = t => console.log("  ✅ " + t), warn = t => console.log("  ⚠️  " + t);
(async () => {
  console.log("\n🦸 Little Hero Bot · setup\n");
  const rl = readline.createInterface({ input: stdin, output: stdout });
  let G = String(process.env.LHH_GUILD || process.argv[2] || "").replace(/\D/g, "");
  TOKEN = String(process.env.LHH_TOKEN || "").trim();
  for (let i = 0; !TOKEN && i < 5; i++) TOKEN = (await rl.question("Paste your bot token, then press Enter: ")).trim();
  for (let i = 0; !/^\d{15,22}$/.test(G) && i < 5; i++) G = (await rl.question("Paste your server ID, then press Enter: ")).replace(/\D/g, "");
  let app;
  try { app = await api("GET", "/applications/@me"); } catch (e) { console.log(e.status === 401 ? "That bot token isn't right. Reset it in the Developer Portal and copy it again." : "Couldn't reach Discord: " + e.message); process.exit(1); }
  let guild; try { guild = await api("GET", `/guilds/${G}`); } catch { console.log("The bot isn't in that server yet. Open the invite link below, add it, then run this again.\n"); console.log(invite(app.id)); process.exit(1); }
  console.log(`Bot app: ${app.name}   Server: ${guild.name}\n`);

  console.log("1/4 Name and logo");
  try { await api("PATCH", "/applications/@me", { description: "The official Little Hero Health bot: moderation, reports and team applications. 🦸", icon: ICON }); ok("App icon and description"); } catch (e) { warn("App icon: " + e.message); }
  try { await api("PATCH", "/users/@me", { username: "Little Hero Bot", avatar: ICON }); ok("Bot name: Little Hero Bot, with your logo"); } catch (e) { warn("Bot name/avatar: " + e.message + " (you can set these in the Developer Portal → Bot)"); }
  try { await api("PATCH", `/guilds/${G}/members/@me`, { nick: "Little Hero Bot" }); } catch {}

  console.log("\n2/4 Slash commands");
  try { const c = await api("PUT", `/applications/${app.id}/guilds/${G}/commands`, COMMANDS); ok(`${c.length} commands: /warn /timeout /untimeout /kick /ban /clear /apply /rules /play + Report to moderators`); }
  catch (e) { warn("Commands: " + e.message); }

  console.log("\n3/4 Admin role and #staff-applications");
  try {
    const roles = await api("GET", `/guilds/${G}/roles`);
    if (roles.find(r => r.name === "⭐ Admin")) ok("⭐ Admin role already there");
    else {
      const P = [10, 11, 16, 6, 14, 15, 13, 1, 2, 40, 34, 22, 24, 7, 27, 20, 21].reduce((a, b) => a | (1n << BigInt(b)), 0n).toString();
      await api("POST", `/guilds/${G}/roles`, { name: "⭐ Admin", color: 0xE0B800, hoist: true, mentionable: true, permissions: P }); ok("Made the ⭐ Admin role (moderator powers plus ban, audit log and nicknames)");
    }
  } catch (e) { warn("Admin role: " + e.message); }
  try {
    const chans = await api("GET", `/guilds/${G}/channels`);
    if (chans.find(c => c.name === "staff-applications")) ok("Already there");
    else {
      const staff = chans.find(c => c.type === 4 && /staff only/i.test(c.name));
      const body = { name: "staff-applications", type: 0, topic: "Admin and Moderator applications from /apply. Only the Owner and Grown-up Admins can tap Accept or Deny." };
      if (staff) { body.parent_id = staff.id; body.permission_overwrites = staff.permission_overwrites; }
      else body.permission_overwrites = [{ id: G, type: 0, allow: "0", deny: (1n << 10n).toString() }];
      await api("POST", `/guilds/${G}/channels`, body); ok("Made #staff-applications (private)");
    }
  } catch (e) { warn("Channel: " + e.message); }

  console.log("\n4/4 Connect to Cloudflare");
  console.log(`  Put these in Cloudflare → your worker → Settings → Variables and Secrets:`);
  console.log(`     DISCORD_APPLICATION_ID = ${app.id}`);
  console.log(`     DISCORD_PUBLIC_KEY     = ${app.verify_key}`);
  console.log(`     DISCORD_TOKEN          = (your bot token, as a Secret)`);
  let url = String(process.env.LHH_URL ?? "").trim();
  if (!process.env.LHH_URL) url = (await rl.question("\n  Paste your worker URL (https://....workers.dev), or press Enter to do this later: ")).trim();
  rl.close();
  if (url) {
    try { await api("PATCH", "/applications/@me", { interactions_endpoint_url: url.replace(/\/$/, "") }); ok("Connected! Discord checked your worker and it answered."); }
    catch (e) { warn("Discord couldn't reach your worker. Check the 3 settings above are saved and deployed, then run this again. (" + e.message + ")"); }
  }
  console.log(`
🎉 Little Hero Bot is ready!
Last steps in Discord:
  1. Server Settings → Roles → drag "Little Hero Bot" ABOVE ⭐ Admin and 🛡️ Moderator,\n     and drag ⭐ Admin just below 🧑‍💼 Grown-up Admin.
  2. Try it: type /rules in #general. Right-click any message → Apps → Report to moderators.
  3. Post in #announcements: "Want to help run the server? Type /apply to be an Admin or Moderator!"
Need to re-invite the bot with the right permissions? Use:
${invite(app.id)}
`);
})().catch(e => { console.log("\nSomething went wrong: " + e.message); process.exit(1); });
function invite(id) {
  const p = [10, 11, 14, 16, 13, 1, 2, 28, 40].reduce((a, b) => a | (1n << BigInt(b)), 0n);
  return `https://discord.com/oauth2/authorize?client_id=${id}&scope=bot%20applications.commands&permissions=${p}`;
}
